'use strict';
const assert = require('assert');
const fs = require('fs');
const path = require('path');
const cad = require('../api/_lib/cast-cad-production');

const state = cad.resetState();
const owner = { id: 'u1', role: 'Owner Admin', name: 'Owner', email: 'owner@example.com', authenticated: true };
const readOnly = { id: 'u2', role: 'Read Only Viewer', name: 'Viewer', email: 'viewer@example.com', authenticated: true };

assert.equal(cad.canCastCad('Owner Admin', 'delete_markup'), true, 'owner admin can delete markups');
assert.equal(cad.canCastCad('Read Only Viewer', 'create_markup'), false, 'read only cannot create markups');

const blockedPdf = cad.buildPdfStreamContract({ sheet: { path: 'Current Drawings/A/A-101.pdf', name: 'A-101.pdf', extension: 'pdf' }, actor: readOnly });
assert.equal(blockedPdf.ok, false, 'PDF stream fails closed without provider configuration');
assert.equal(blockedPdf.status, 503, 'PDF stream reports provider-required status');
assert.equal(blockedPdf.contract.publicExposure, false, 'PDF stream contract forbids public exposure');
assert.equal(blockedPdf.contract.requiresAuth, true, 'PDF stream contract requires auth');
const pdfLease = cad.createPdfStreamLease(state, { projectId: 'alum', sheet: { path: 'Current Drawings/A/A-101.pdf', name: 'A-101.pdf', extension: 'pdf' } }, readOnly);
assert.equal(pdfLease.ok, false, 'PDF stream lease fails closed without provider configuration');
assert.equal(pdfLease.lease.publicExposure, false, 'PDF stream lease forbids public exposure');
assert.equal(pdfLease.lease.requiresAuth, true, 'PDF stream lease requires authenticated access');
assert.deepEqual(pdfLease.lease.requiredEnvVars, ['CAST_CAD_PDF_STREAM_BASE or DROPBOX_ACCESS_TOKEN or CAST_SERVER_DOCUMENT_API_URL'], 'PDF stream lease names required provider env choices');
assert.ok(state.auditLog.some((row) => row.entityType === 'CAST_CAD_PDF_STREAM_LEASE'), 'PDF stream lease request is audited even when provider-blocked');
const publicRenderer = cad.createPdfRendererSession(state, { projectId: 'alum', sheetId: 'A-101', sourcePointer: 'https://example.com/A-101.pdf' }, readOnly);
assert.equal(publicRenderer.ok, false, 'PDF renderer sessions reject public PDF URLs');
assert.equal(publicRenderer.code, 'public-url-forbidden', 'PDF renderer public URL blocker is explicit');
const rendererSession = cad.createPdfRendererSession(state, { projectId: 'alum', sheetId: 'A-101', streamLeaseId: 'lease:cad_pdf_stream_123', outputs: ['thumbnail-manifest','text-search-index','viewport-matrices'] }, readOnly);
assert.equal(rendererSession.ok, false, 'PDF renderer session fails closed without a renderer worker');
assert.equal(rendererSession.code, 'provider-required', 'PDF renderer session exposes provider-required blocker');
assert.equal(rendererSession.rendererSession.publicExposure, false, 'PDF renderer session forbids public exposure');
assert.equal(rendererSession.rendererSession.privateArtifacts, true, 'PDF renderer session keeps render artifacts private/no-store');
assert.equal(rendererSession.rendererSession.outputPointer, '', 'PDF renderer session does not fabricate thumbnail/search/bookmark artifacts');
assert.deepEqual(rendererSession.requiredEnvVars, ['CAST_CAD_PDF_RENDERER_WORKER or CAST_CAD_PDFJS_WORKER_URL or CAST_CAD_PDF_SDK_PROVIDER'], 'PDF renderer session names exact renderer worker/provider env choices');
assert.equal(cad.listPdfRendererSessions(state, { projectId: 'alum', sheetId: 'A-101' }).length, 1, 'PDF renderer sessions list by project/sheet');
assert.ok(cad.pdfRendererContract().outputs.includes('viewport-matrices'), 'PDF renderer contract includes viewport matrices needed by coordinate mapping');
assert.ok(state.auditLog.some((row) => row.entityType === 'CAST_CAD_PDF_RENDERER_SESSION'), 'PDF renderer session attempts are audited');
const previousPdfRequireAuth = process.env.CAST_CAD_REQUIRE_AUTH;
process.env.CAST_CAD_REQUIRE_AUTH = 'true';
const unauthenticatedPdfLease = cad.createPdfStreamLease(state, { projectId: 'alum', sheet: { path: 'Current Drawings/A/A-101.pdf', name: 'A-101.pdf', extension: 'pdf' } }, { id: 'anon', role: 'Read Only Viewer', authenticated: false });
assert.equal(unauthenticatedPdfLease.ok, false, 'PDF stream lease fails closed when strict auth is enabled without a session identity');
assert.equal(unauthenticatedPdfLease.code, 'auth-required', 'PDF stream lease exposes strict auth blocker');
if (previousPdfRequireAuth === undefined) delete process.env.CAST_CAD_REQUIRE_AUTH; else process.env.CAST_CAD_REQUIRE_AUTH = previousPdfRequireAuth;

const markup = cad.createMarkup(state, { projectId: 'alum', sheetId: 'A-101', tool: 'Area Measurement', subject: 'Test area', layer: 'ASI-002', group_id: 'grp-envelope', style: { stroke: '#2563eb', fill: 'rgba(37,99,235,.2)', opacity: 0.75, lineWidth: 4, fontSize: 14 }, measurement: { value: 245.5, unit: 'SF' }, geometry: { type: 'polygon', points: [{x:1,y:1},{x:5,y:1},{x:5,y:5}] } }, owner);
assert.equal(markup.ok, true, 'markup creates through production service');
assert.equal(markup.markup.layer, 'ASI-002', 'markup create stores layer');
assert.equal(markup.markup.groupId, 'grp-envelope', 'markup create stores group');
assert.equal(markup.markup.style.opacity, 0.75, 'markup create stores opacity');
assert.ok(state.auditLog.some((row) => row.entityId === markup.markup.id), 'markup creation is audited');

const denied = cad.createMarkup(state, { projectId: 'alum', sheetId: 'A-101', tool: 'Pin', subject: 'Blocked' }, readOnly);
assert.equal(denied.ok, false, 'read-only markup creation is denied');
assert.equal(denied.status, 403, 'read-only denial is a 403 contract');

const updated = cad.updateMarkup(state, markup.markup.id, { status: 'Resolved', layer: 'ASI-001', cost_code: '09-2116', assignee_user_id: 'u4' }, owner);
assert.equal(updated.ok, true, 'markup updates through production service');
assert.equal(updated.markup.status, 'Resolved', 'markup status persists');
assert.equal(updated.markup.layer, 'ASI-001', 'markup layer persists');
assert.equal(updated.markup.costCode, '09-2116', 'markup update accepts snake_case cost code from API payloads');
assert.equal(updated.markup.assigneeUserId, 'u4', 'markup update accepts snake_case assignee from API payloads');
const savedMarkupView = cad.createSavedMarkupView(state, { projectId: 'alum', name: 'ASI drywall open items', filters: { sheetId: 'A-101', layer: 'ASI-001', costCode: '09-2116', assigneeUserId: 'u4' } }, owner);
assert.equal(savedMarkupView.ok, true, 'saved markup filter/report view creates through production service');
assert.equal(savedMarkupView.previewCount, 1, 'saved markup view previews matching filtered rows');
assert.equal(savedMarkupView.view.publicExposure, false, 'saved markup view report forbids public exposure');
assert.equal(savedMarkupView.view.privateReport, true, 'saved markup view is a private report contract');
assert.equal(cad.listSavedMarkupViews(state, { projectId: 'alum' }).length, 1, 'saved markup views list by project');
const rerunSavedMarkupView = cad.runSavedMarkupView(state, savedMarkupView.view.id);
assert.equal(rerunSavedMarkupView.ok, true, 'saved markup view reruns stored filters');
assert.equal(rerunSavedMarkupView.count, 1, 'saved markup view rerun returns matching markups');
assert.equal(cad.listMarkups(state, { projectId: 'alum', layer: 'ASI-001', cost_code: '09-2116', assignee_user_id: 'u4' }).length, 1, 'markup list accepts advanced filter dimensions and snake_case aliases');
assert.ok(state.auditLog.some((row) => row.entityType === 'CAST_CAD_MARKUP_VIEW'), 'saved markup views are audited');

const markupToDelete = cad.createMarkup(state, { projectId: 'alum', sheetId: 'A-101', tool: 'Pin', subject: 'Delete contract test' }, owner);
assert.equal(markupToDelete.ok, true, 'markup for delete contract creates');
const softDeleted = cad.deleteMarkup(state, markupToDelete.markup.id, { reason: 'Duplicate pin' }, owner);
assert.equal(softDeleted.ok, true, 'markup soft-delete succeeds through audited production service');
assert.equal(softDeleted.markup.status, 'Deleted', 'soft-deleted markup is marked Deleted');
assert.equal(cad.listMarkups(state, { projectId: 'alum', sheetId: 'A-101' }).some((row) => row.id === markupToDelete.markup.id), false, 'soft-deleted markups are excluded from default lists/exports');
assert.equal(cad.listMarkups(state, { projectId: 'alum', sheetId: 'A-101', includeDeleted: true }).some((row) => row.id === markupToDelete.markup.id), true, 'deleted markups remain discoverable when includeDeleted is explicit');
const blockedHardDelete = cad.deleteMarkup(state, markupToDelete.markup.id, { hardDelete: true }, owner);
assert.equal(blockedHardDelete.ok, false, 'permanent markup deletion fails closed without human review');
assert.equal(blockedHardDelete.code, 'human-review-required', 'permanent deletion exposes human review blocker');
const deniedDelete = cad.deleteMarkup(state, markup.markup.id, {}, readOnly);
assert.equal(deniedDelete.ok, false, 'read-only users cannot delete markups');
assert.equal(deniedDelete.status, 403, 'read-only delete denial is a 403');
assert.ok(state.auditLog.some((row) => row.action === 'Soft-deleted CAST CAD markup'), 'markup soft-delete is audited');

const comment = cad.createMarkupComment(state, markup.markup.id, { body: 'Please confirm with @architect@example.com and @pm-team.' }, owner);
assert.equal(comment.ok, true, 'threaded markup comment creates through production service');
assert.deepEqual(comment.comment.mentions, ['architect@example.com', 'pm-team'], 'comment contract extracts email and handle mentions');
const reply = cad.createMarkupComment(state, markup.markup.id, { parentId: comment.comment.id, body: 'Confirmed in review room.' }, owner);
assert.equal(reply.ok, true, 'threaded markup replies enforce parent linkage');
const badReply = cad.createMarkupComment(state, markup.markup.id, { parentId: 'other-thread', body: 'bad parent' }, owner);
assert.equal(badReply.ok, false, 'threaded markup replies reject parents outside the same markup');
assert.equal(cad.listMarkupComments(state, markup.markup.id).length, 2, 'markup comments list by markup');
const mentionDelivery = cad.createCommentMentionDelivery(state, { commentId: comment.comment.id }, owner);
assert.equal(mentionDelivery.ok, false, 'mention notification delivery fails closed without email/realtime transport');
assert.equal(mentionDelivery.code, 'provider-required', 'mention notification exposes provider-required blocker');
assert.equal(mentionDelivery.mentionEvent.publicExposure, false, 'mention notification contract forbids public exposure');
assert.equal(mentionDelivery.mentionEvent.noPublicLinks, true, 'mention notification contract forbids public links');
assert.deepEqual(mentionDelivery.mentionEvent.requiredEnvVars, ['CAST_CAD_COMMENT_NOTIFICATION_TRANSPORT or CAST_CAD_EMAIL_PROVIDER or CAST_CAD_REALTIME_PROVIDER'], 'mention notification names exact transport env choices');
assert.equal(cad.listCommentMentionEvents(state, { markupId: markup.markup.id }).length, 1, 'mention notification events list by markup');
assert.ok(cad.listMarkupAudit(state, markup.markup.id).some((row) => row.entityType === 'CAST_CAD_MARKUP_COMMENT'), 'markup audit history includes thread comments');
assert.ok(cad.listMarkupAudit(state, markup.markup.id).some((row) => row.entityType === 'CAST_CAD_COMMENT_MENTION'), 'markup audit history includes mention notification events');
const badAttachment = cad.createMarkupAttachment(state, { projectId: 'alum', markupId: markup.markup.id, originalFileName: 'field-photo.exe', contentType: 'application/x-msdownload', byteSize: 100, contentHash: 'sha256-bad' }, owner);
assert.equal(badAttachment.ok, false, 'markup attachments reject unsafe evidence file types');
const attachment = cad.createMarkupAttachment(state, { projectId: 'alum', sheetId: 'A-101', markupId: markup.markup.id, commentId: comment.comment.id, originalFileName: 'field-photo.png', contentType: 'image/png', byteSize: 2048, contentHash: 'sha256-field-photo', caption: 'Field condition photo' }, owner);
assert.equal(attachment.ok, true, 'private markup attachment manifest registers through production service');
assert.equal(attachment.attachment.publicExposure, false, 'attachment manifest forbids public exposure');
assert.equal(attachment.attachment.requiresAuth, true, 'attachment manifest requires auth-backed private access');
assert.equal(attachment.attachment.providerRequired, true, 'attachment manifest names missing private storage adapter without faking durable bytes');
assert.deepEqual(attachment.attachment.requiredEnvVars, ['CAST_CAD_ATTACHMENT_STORAGE_ADAPTER'], 'attachment contract exposes required storage adapter env var');
const blockedDurableAttachment = cad.createMarkupAttachment(state, { projectId: 'alum', sheetId: 'A-101', markupId: markup.markup.id, originalFileName: 'signed.pdf', contentType: 'application/pdf', byteSize: 4096, contentHash: 'sha256-signed', durable: true }, owner);
assert.equal(blockedDurableAttachment.ok, false, 'durable attachment upload fails closed without storage adapter');
assert.equal(blockedDurableAttachment.code, 'provider-required', 'durable attachment blocker is provider-required');
assert.equal(cad.listMarkupAttachments(state, { markupId: markup.markup.id }).length, 1, 'attachment list filters by markup');
assert.ok(cad.listMarkupAudit(state, markup.markup.id).some((row) => row.entityType === 'CAST_CAD_ATTACHMENT'), 'markup audit history includes attachment manifests');

const workbook = cad.createTakeoffWorkbookExport(state, { projectId: 'alum', sheetId: 'A-101' }, owner);
assert.equal(workbook.ok, true, 'takeoff workbook export job created');
assert.equal(workbook.exportJob.status, 'provider-required', 'takeoff workbook fails closed until the XLSX worker is configured');
assert.equal(workbook.exportJob.rows.length, 1, 'takeoff workbook includes measured markup');
assert.equal(workbook.exportJob.outputPointer, '', 'takeoff workbook contract does not fabricate a private XLSX artifact pointer without a worker');
assert.deepEqual(workbook.exportJob.requiredEnvVars, ['CAST_CAD_TAKEOFF_WORKBOOK_WORKER or CAST_CAD_XLSX_EXPORT_WORKER'], 'takeoff workbook names exact worker env requirements');

const pdfExport = cad.createAnnotatedPdfExport(state, { projectId: 'alum', sheetId: 'A-101' }, owner);
assert.equal(pdfExport.ok, true, 'annotated PDF export contract created');
assert.equal(pdfExport.exportJob.status, 'provider-required', 'annotated PDF export fails open as worker-required job, not fake success');
assert.deepEqual(pdfExport.exportJob.requiredEnvVars, ['CAST_CAD_PDF_EXPORT_WORKER'], 'annotated PDF export names exact worker env var');
assert.equal(pdfExport.exportJob.privateArtifacts, true, 'annotated PDF export contract keeps artifacts private/no-store');
const publicAnnotationImport = cad.createPdfAnnotationImportJob(state, { projectId: 'alum', sheetId: 'A-101', sourcePointer: 'https://example.com/public.pdf' }, owner);
assert.equal(publicAnnotationImport.ok, false, 'PDF annotation import rejects public source URLs');
assert.equal(publicAnnotationImport.code, 'public-url-forbidden', 'PDF annotation import exposes public URL blocker');
const annotationImport = cad.createPdfAnnotationImportJob(state, { projectId: 'alum', sheetId: 'A-101', sourcePointer: 'lease:cad_pdf_stream_123', mode: 'import-unflattened' }, owner);
assert.equal(annotationImport.ok, true, 'PDF annotation import/unflatten job contract creates');
assert.equal(annotationImport.exportJob.status, 'provider-required', 'PDF annotation import fails closed until import worker is configured');
assert.equal(annotationImport.exportJob.publicExposure, false, 'PDF annotation import forbids public exposure');
assert.deepEqual(annotationImport.exportJob.requiredEnvVars, ['CAST_CAD_PDF_ANNOTATION_IMPORT_WORKER or CAST_CAD_PDF_EXPORT_WORKER'], 'PDF annotation import names exact worker env choices');
