const blockedCurrentDoc = cad.upsertDrawingDocumentMetadata(state, { projectId: 'alum', setId: 'current', sheetId: 'A-102', drawingNumber: 'A-102', sourcePath: 'Current Drawings/A/A-102.pdf', status: 'current' }, owner);
